import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.DJWFW3S-.js";const h=JSON.parse('{"title":"Analysis","description":"","frontmatter":{"title":"Analysis"},"headers":[],"relativePath":"en/api/analysis.md","filePath":"en/api/analysis.md"}'),l={name:"en/api/analysis.md"};function d(o,e,n,r,m,y){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="analysis" tabindex="-1">Analysis <a class="header-anchor" href="#analysis" aria-label="Permalink to &quot;Analysis&quot;">​</a></h1><p>Analysis is the base class of 3D spatial analysis, defining methods common to all kinds of 3D spatial analysis.</p><p>Analysis can only be added to a GroupGLLayer; it cannot be added to other WebGL layers.</p><blockquote><p>Note: In the source, the subclasses of Analysis include CutAnalysis (section cut), ViewshedAnalysis (viewshed), SkylineAnalysis (skyline), FloodAnalysis (flood), InSightAnalysis (intervisibility), CrossCutAnalysis (cross-section) and HeightLimitAnalysis (height limit, inheriting from FloodAnalysis). ExcavateAnalysis (excavation) does not inherit from Analysis; it inherits ExtrudePolygonLayer from <code>@maptalks/vt</code>, so it is out of scope for this page.</p></blockquote><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><blockquote><p>This document has been cross-checked against the maptalks-gl 0.124.4 source</p></blockquote><h3 id="other-public-methods-of-analysis" tabindex="-1">Other Public Methods of Analysis <a class="header-anchor" href="#other-public-methods-of-analysis" aria-label="Permalink to &quot;Other Public Methods of Analysis&quot;">​</a></h3><details><summary>addTo(layer)</summary><div><br><p>Adds the analysis to a layer, creating its render pass once the layer is on a map.</p><p>Parameters:</p><ul><li>layer <code>Any</code></li></ul></div></details><details><summary>enable()</summary><div><br><p>Enables the analysis and requests a redraw of its layer.</p></div></details><details><summary>disable()</summary><div><br><p>Disables the analysis and requests a redraw of its layer.</p></div></details><details><summary>isEnable()</summary><div><br><p>Returns whether the analysis is currently enabled.</p></div></details><details><summary>remove()</summary><div><br><p>Removes the analysis from its layer and disposes its passes, meshes and picking resources.</p></div></details><details><summary>update(name, value)</summary><div><br><p>Updates the named analysis option and requests a redraw of its layer.</p><p>Parameters:</p><ul><li>name <code>Any</code></li><li>value <code>Any</code></li></ul></div></details><details><summary>getExcludeLayers()</summary><div><br><p>Returns the ids of the layers excluded from the analysis.</p></div></details><details><summary>setExcludeLayers(layerIds)</summary><div><br><p>Sets the ids of the layers to be excluded from the analysis.</p><p>Parameters:</p><ul><li>layerIds <code>Any</code></li></ul></div></details><details><summary>exportAnalysisMap(meshes)</summary><div><br><p>Renders the analysis pass for the given meshes and reads back its RGBA pixels, null when disabled.</p><p>Parameters:</p><ul><li>meshes <code>Any</code></li></ul></div></details><details><summary>getAnalysisType()</summary><div><br><p>Returns the analysis type identifier, such as cut or viewshed.</p></div></details><h3 id="mixed-in-methods" tabindex="-1">Mixed-in Methods <a class="header-anchor" href="#mixed-in-methods" aria-label="Permalink to &quot;Mixed-in Methods&quot;">​</a></h3><p>This class gains the following method groups from mixins; see the linked pages for details: <a href="/en/api/eventable.html">Eventable</a>（<code>on</code>、<code>addEventListener</code>、<code>once</code>、<code>off</code>、<code>removeEventListener</code>、<code>listens</code>、<code>getListeningEvents</code>、<code>copyEventListeners</code>…）；<a href="/en/api/handlerable.html">Handlerable</a>.</p>',19)])])}const p=s(l,[["render",d]]);export{h as __pageData,p as default};
